return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'BuddyPress Activity Filter','pot-creation-date'=>'2026-07-29T13:44:54+00:00','po-revision-date'=>'2025-07-29 01:21+0530','x-generator'=>'Poedit 3.5','messages'=>['BuddyPress Activity Filter'=>'BuddyPress Filtrage des Activités','https://wordpress.org/plugins/bp-activity-filter/'=>'https://wbcomdesigns.com/downloads/buddypress-activity-filter/','Hide activity types from BuddyPress activity streams and set the default filter members see.'=>'Masquez des types d\'activité dans les flux d\'activité BuddyPress et définissez le filtre par défaut vu par les membres.','Wbcom Designs'=>'Wbcom Designs','https://wbcomdesigns.com/'=>'https://wbcomdesigns.com/','BuddyPress Activity Filter requires BuddyPress to be installed and active.'=>'Filtrage des Activités nécessite d\'être activé sur le blog où BuddyPress est activé.','Plugin Activation Error'=>'Erreur d’activation de l’extension','Settings'=>'Paramètres','This plugin requires %s to be installed and active.'=>'Ce plugin nécessite que %s soit installé et actif.','This plugin requires BuddyPress version %1$s or higher. You are running version %2$s.'=>'Ce plugin nécessite la version %1$s ou supérieure de BuddyPress. Vous utilisez la version %2$s.','This plugin is not compatible with BuddyBoss due to similar built-in features. Please use BuddyBoss\'s native activity filtering instead.'=>'Ce plugin n\'est pas compatible avec BuddyBoss en raison de fonctionnalités intégrées similaires. Veuillez utiliser le filtre d\'activité natif de BuddyBoss à la place.','Cloning instances of this class is forbidden.'=>'Le clonage des instances de cette classe est interdit.','Unserializing instances of this class is forbidden.'=>'La désérialisation des instances de cette classe est interdite.','Default Filters'=>'Filtres par défaut','Hidden Activities'=>'Activités masquées','FAQ'=>'FAQ','More Free Tools from Wbcom Designs'=>'Dernières nouvelles de Wbcom Designs','How do I set a default filter for all activity streams?'=>'Comment définir un filtre par défaut pour tous les flux d\'activité ?','Open the Default Filters tab and pick a default from the site-wide dropdown. It applies automatically the first time someone loads the activity stream.'=>'Accédez à l\'onglet Filtres par défaut et sélectionnez le filtre par défaut de votre choix dans la liste déroulante. Ce filtre sera appliqué automatiquement lorsque les utilisateurs visiteront le flux d\'activités.','Can I set a different default filter for profiles?'=>'Puis-je définir différents filtres par défaut pour les pages de profil ?','How do I hide specific activity types?'=>'Comment masquer des types d\'activités spécifiques aux utilisateurs ?','Why are some activities missing from the filter?'=>'Pourquoi certaines activités n\'apparaissent-elles pas dans le filtre ?','Check the Hidden Activities tab to confirm the type is not hidden. Some system activity types may also be unavailable if another plugin has disabled them.'=>'Vérifiez l\'onglet Activités cachées pour vous assurer que le type d\'activité n\'est pas caché. De plus, certains types d\'activités peuvent ne pas avoir d\'option de filtrage s\'il s\'agit d\'activités système ou si elles ont été désactivées par d\'autres plugins.','Is this plugin compatible with BuddyBoss Platform?'=>'Ce plugin est-il compatible avec la plateforme BuddyBoss ?','No. This plugin is built for BuddyPress. BuddyBoss Platform has its own activity filtering, so this plugin is not needed and is not fully compatible with it.'=>'BuddyPress Activity Filter est conçu spécifiquement pour BuddyPress. La plateforme BuddyBoss comprend ses propres fonctions de filtrage d\'activité, ce plugin n\'est donc pas nécessaire et peut ne pas être entièrement compatible avec BuddyBoss.','How do filters affect activity stream performance?'=>'Comment les filtres affectent-ils les performances du flux d\'activité ?','Frequently Asked Questions'=>'Questions fréquentes','Where can I get support or report issues?'=>'Où puis-je obtenir de l\'aide ou signaler des problèmes ?','Open settings'=>'Ouvrir les réglages','About WB Plugins'=>'À propos de WB Plugins','Default Activity Filters'=>'Filtres d\'activité par défaut','Site-wide stream default'=>'Valeur par défaut du flux global','Everything'=>'Tout','Applied to the main site-wide activity stream the first time a visitor loads it.'=>'Filtre par défaut appliqué au flux d\'activité principal du site. Les utilisateurs peuvent toujours le modifier à l\'aide du menu déroulant du filtre d\'activité.','Profile stream default'=>'Valeur par défaut du flux de profil','Posted a status update'=>'Publié une mise à jour de statut','Replied to a status update'=>'A répondu à une mise à jour de statut','Hidden Activity Types'=>'Types d\'activité masqués','No activity types are available. Make sure BuddyPress is installed and active.'=>'Aucun type d\'activité n\'est disponible. Assurez-vous que BuddyPress est correctement installé et activé.','Core activities (always visible)'=>'Activités de base (toujours disponibles)','Other activity types'=>'Autres types d\'activité','Check a box to hide that activity type from your site.'=>'Cochez les cases ci-dessous pour masquer ces types d\'activité sur votre site.','Hide activity types from your activity streams and set the default filter members see.'=>'Masquez des types d\'activité dans vos flux d\'activité et définissez le filtre par défaut vu par les membres.','Activity Filter'=>'Filtrage des activités','Plugin'=>'Extension','Activity Filter navigation'=>'Navigation du filtrage des activités','Documentation'=>'Documentation','Save Settings'=>'Sauvegarder les paramètres']];